const now = new Date();
const lookbackDays = $input.first().json.lookback_days || 7;
const since = new Date(now.getTime() - lookbackDays * 24 * 60 * 60 * 1000);

return [{
  json: {
    ...$input.first().json,
    since_iso: since.toISOString(),
    until_iso: now.toISOString(),
    since_display: since.toISOString().split('T')[0],
    until_display: now.toISOString().split('T')[0]
  }
}];

const vars = $('Compute Date Range').first().json;
const sinceDate = new Date(vars.since_iso);

// --- Commits ---
let rawCommits = [];
try {
  rawCommits = $('Fetch Commits').all().map(i => i.json);
  // Handle case where the response is a single array
  if (rawCommits.length === 1 && Array.isArray(rawCommits[0])) {
    rawCommits = rawCommits[0];
  }
} catch (e) { rawCommits = []; }

const commits = (Array.isArray(rawCommits) ? rawCommits : [])
  .filter(c => c && c.commit)
  .map(c => ({
    sha: (c.sha || '').substring(0, 7),
    message: (c.commit.message || '').split('\n')[0].substring(0, 120),
    author: c.commit.author?.name || c.author?.login || 'unknown',
    date: c.commit.author?.date || ''
  }));

// --- Closed Issues (exclude PRs) ---
let rawIssues = [];
try {
  rawIssues = $('Fetch Closed Issues').all().map(i => i.json);
  if (rawIssues.length === 1 && Array.isArray(rawIssues[0])) {
    rawIssues = rawIssues[0];
  }
} catch (e) { rawIssues = []; }

const issues = (Array.isArray(rawIssues) ? rawIssues : [])
  .filter(i => i && !i.pull_request && i.closed_at && new Date(i.closed_at) >= sinceDate)
  .map(i => ({
    number: i.number,
    title: (i.title || '').substring(0, 120),
    labels: (i.labels || []).map(l => l.name).join(', '),
    closed_at: i.closed_at
  }));

// --- Merged PRs ---
let rawPRs = [];
try {
  rawPRs = $('Fetch Merged PRs').all().map(i => i.json);
  if (rawPRs.length === 1 && Array.isArray(rawPRs[0])) {
    rawPRs = rawPRs[0];
  }
} catch (e) { rawPRs = []; }

const mergedPRs = (Array.isArray(rawPRs) ? rawPRs : [])
  .filter(p => p && p.merged_at && new Date(p.merged_at) >= sinceDate)
  .map(p => ({
    number: p.number,
    title: (p.title || '').substring(0, 120),
    author: p.user?.login || 'unknown',
    merged_at: p.merged_at,
    labels: (p.labels || []).map(l => l.name).join(', ')
  }));

return [{
  json: {
    ...vars,
    stats: {
      total_commits: commits.length,
      total_issues_closed: issues.length,
      total_prs_merged: mergedPRs.length
    },
    commits,
    issues,
    mergedPRs
  }
}];

const data = $input.first().json;
const lang = (data.language || 'EN').toUpperCase();

const langInstruction = lang === 'FR'
  ? 'Write the entire summary in French (Fran\u00e7ais).'
  : lang === 'ES'
  ? 'Write the entire summary in Spanish (Espa\u00f1ol).'
  : lang === 'ZH'
  ? 'Write the entire summary in Chinese (\u4e2d\u6587).'
  : lang === 'DE'
  ? 'Write the entire summary in German (Deutsch).'
  : lang === 'JA'
  ? 'Write the entire summary in Japanese (\u65e5\u672c\u8a9e).'
  : 'Write the entire summary in English.';

const systemPrompt = `You are a senior engineering lead writing a weekly development summary for your team. Your summaries are concise, insightful, and highlight what matters most. ${langInstruction}`;

const userPrompt = `Generate a narrative weekly development summary for the GitHub repository **${data.github_owner}/${data.github_repo}** covering ${data.since_display} to ${data.until_display}.

## Raw Data

### Commits (${data.stats.total_commits})
${data.commits.length > 0 ? data.commits.map(c => `- \`${c.sha}\` ${c.message} (by ${c.author})`).join('\n') : 'No commits this period.'}

### Closed Issues (${data.stats.total_issues_closed})
${data.issues.length > 0 ? data.issues.map(i => `- #${i.number}: ${i.title}${i.labels ? ' [' + i.labels + ']' : ''}`).join('\n') : 'No issues closed this period.'}

### Merged PRs (${data.stats.total_prs_merged})
${data.mergedPRs.length > 0 ? data.mergedPRs.map(p => `- PR #${p.number}: ${p.title} (by ${p.author})${p.labels ? ' [' + p.labels + ']' : ''}`).join('\n') : 'No PRs merged this period.'}

## Instructions
1. Start with a one-line TL;DR of the week.
2. Group related changes into 2-4 themes (e.g., "New Features", "Bug Fixes", "Infrastructure").
3. Under each theme, summarize what changed and why it matters. Reference PR/issue numbers.
4. End with a short "Looking Ahead" section noting any open threads or upcoming work implied by the changes.
5. Keep the total summary under 500 words.
6. Use markdown formatting.
7. If there is no activity, write a brief "quiet week" summary instead of making things up.`;

return [{
  json: {
    ...data,
    claude_system_prompt: systemPrompt,
    claude_user_prompt: userPrompt
  }
}];

const input = $input.first().json;
const vars = $('Build Claude Prompt').first().json;

// Extract the summary text from Claude's response
let summary = '';
try {
  const body = input.body || input;
  if (body.content && Array.isArray(body.content)) {
    summary = body.content
      .filter(block => block.type === 'text')
      .map(block => block.text)
      .join('\n');
  } else if (typeof body === 'string') {
    summary = body;
  }
} catch (e) {
  summary = 'Error extracting summary: ' + e.message;
}

if (!summary || summary.trim().length === 0) {
  summary = 'No summary was generated. The Claude API may have returned an empty response.';
}

// Build the final output
const header = `# Weekly Dev Summary: ${vars.github_owner}/${vars.github_repo}`;
const dateRange = `**${vars.since_display}** to **${vars.until_display}**`;
const statsLine = `Commits: ${vars.stats.total_commits} | Issues closed: ${vars.stats.total_issues_closed} | PRs merged: ${vars.stats.total_prs_merged}`;

const fullSummary = `${header}\n${dateRange} | ${statsLine}\n\n---\n\n${summary}`;

// Truncate for Discord (2000 char limit)
const discordSummary = fullSummary.length > 1950
  ? fullSummary.substring(0, 1950) + '\n\n... _(truncated)_'
  : fullSummary;

return [{
  json: {
    ...vars,
    summary: fullSummary,
    discord_summary: discordSummary,
    slack_summary: fullSummary,
    email_summary: fullSummary,
    delivery_method: vars.delivery_method
  }
}];
